entries.call:
AngleSceneView(
            scene: vm.scene,
            cameraMode: $vm.cameraMode,
            interactionMode: is3D ? .cameraControl : .tapsOnly,
            autoFitsRotatedTable: !is3D,
            onPocketTapped: { index in
                if !is3D { vm.selectPocket(at: index) }
            },
            draggableBallNodes: vm.draggableBalls,
            onDragBegan: { node in
                hasDraggedOnce = true
                vm.dragBegan(node: node)
            },
            onDragMoved: { node, pos in vm.dragMoved(node: node, worldPosition: pos) },
            onDragEnded: { node in vm.dragEnded(node: node) },
            selectableBallNodes: is3D ? [] : vm.selectableBalls,
            onBallTapped: { node in
                if let key = vm.scene.ballKey(for: node) {
                    vm.selectTarget(key: key)
                }
            }
        )

AngleSceneView(
                scene: vm.scene,
                cameraMode: .constant(cameraMode),
                interactionMode: interactionMode,
                // Anchor-lock only matters in 3D — in 2D the camera is already
                // fixed top-down. The lock guard inside AngleSceneView already
                // bypasses it for non-perspective modes, so this is just an
                // extra defence.
                locksCueBallScreenAnchor: is3D,
                // Landscape uses the same whole-table fitting as Daily Clearance.
                // World ball positions and the question's pocket index stay fixed.
                autoFitsLandscapeTable: !is3D,
                onPocketTapped: nil // Target pocket is fixed by the question; no selection action.
            )

AngleSceneView(
            scene: vm.scene,
            cameraMode: $vm.cameraMode,
            interactionMode: is3D ? .cameraControl : .tapsOnly,
            autoFitsRotatedTable: !is3D && !isDaily2D,
            autoFitsLandscapeTable: isDaily2D,
            onPocketTapped: vm.isBreakMode || vm.isPlaying || isDailyResult ? nil : { vm.selectPocket(at: $0) },
            // P10.1 禁止摆球：非开球模式仅母球可拖（自由球/走位微调）；开球模式拖开球区母球。
            draggableBallNodes: vm.isPlaying || isDailyResult
                || (isDailyClearance && !vm.isBreakMode && dailyController.cuePlacement == .none)
                ? [] : (vm.breakRunner?.draggableCue ?? vm.draggableCueOnly),
            onDragBegan: { node in
                if let runner = vm.breakRunner { runner.dragBegan(node: node) }
                else if isDailyClearance && dailyController.cuePlacement == .none {
                    flash("当前不是自由球，母球不能移动", tone: .warning)
                } else { vm.dragBegan(node: node) }
            },
            onDragMoved: { node, world in
                if let runner = vm.breakRunner {
                    runner.dragMoved(node: node, worldPosition: world)
                } else {
                    if isDailyClearance && dailyController.cuePlacement == .none { return }
                    var constrained = world
                    if isDailyClearance, dailyController.cuePlacement == .behindHeadString {
                        if constrained.x <= AngleSceneCalculator.innerLength / 4 {
                            flash("开球犯规后，请在线后摆放母球", tone: .warning)
                        }
                        constrained.x = max(constrained.x, AngleSceneCalculator.innerLength / 4 + 0.001)
                    }
                    if isDailyClearance {
                        if !vm.moveDailyCue(node: node, world: constrained, placement: dailyController.cuePlacement) {
                            flash("此处不能放球，请移到台内空位", tone: .warning)
                        }
                    } else { vm.dragMoved(node: node, worldPosition: constrained) }
                }
            },
            onDragEnded: { node in
                if let runner = vm.breakRunner { runner.dragEnded(node: node) }
                else if !isDailyClearance || dailyController.cuePlacement != .none {
                    vm.dragEnded(node: node)
                    if isDailyClearance { dailyController.savePlacedBoard() }
                }
            },
            selectableBallNodes: vm.isBreakMode || vm.isPlaying || isDailyResult ? [] :
                (isDailyClearance && is3D ? vm.selectableBalls + vm.draggableCueOnly : vm.selectableBalls),
            onBallTapped: { node in handleTargetTap(node) },
            onTableTapped: is3D || isDailyResult ? nil : { if !vm.isBreakMode { vm.handleTableTap(world: $0) } },
            onAimNudged: is3D || isDailyResult ? nil : {
                if let runner = vm.breakRunner { runner.nudgeAim(byDegrees: $0) }
                else { vm.nudgeFreeAim(byDegrees: $0) }
            },
            onAimDragActiveChanged: { vm.setAimTableDragging($0) },
            projector: projector,
            contentIsAnimating: vm.isPlaying || (vm.breakRunner?.isBusy ?? false)
                || (isDailyClearance && dailyAimWheelIsDragging),
            daily3DDiagnostics: daily3DDiagnostics,
            fpsReadoutTrailingInset: fpsTrailingInset
        )

AngleSceneView(
            scene: vm.scene,
            cameraMode: $vm.cameraMode,
            interactionMode: is3D ? .cameraControl : .tapsOnly,
            autoFitsRotatedTable: !is3D,
            onPocketTapped: is3D || vm.isBreakMode || vm.isPlaying ? nil : { vm.selectPocket(at: $0) },
            // 开球模式：仅母球可拖（限开球区），其余台面交互挂起。
            draggableBallNodes: vm.isPlaying ? [] : (vm.breakRunner?.draggableCue
                ?? (is3D || vm.activeTool == .none ? vm.draggableBalls : [])),
            onDragBegan: { node in
                if let runner = vm.breakRunner { runner.dragBegan(node: node) }
                else { vm.dragBegan(node: node) }
            },
            onDragMoved: { node, world in
                if let runner = vm.breakRunner { runner.dragMoved(node: node, worldPosition: world) }
                else { vm.dragMoved(node: node, worldPosition: world) }
            },
            onDragEnded: { node in
                if let runner = vm.breakRunner { runner.dragEnded(node: node) }
                else { vm.dragEnded(node: node) }
            },
            onDragEndedAt: { node, localPoint in
                guard !vm.isBreakMode else { return }
                handleTableDragEnd(node: node, localPoint: localPoint)
            },
            selectableBallNodes: (is3D || vm.isBreakMode || vm.activeTool != .none) ? [] : vm.selectableBalls,
            onBallTapped: { vm.selectBall(node: $0) },
            // G18/V6：开球模式拖屏调瞄准（G13 相对语义）；非开球模式本页无自由拖瞄，忽略。
            onAimNudged: is3D ? nil : { if let runner = vm.breakRunner { runner.nudgeAim(byDegrees: $0) } },
            projector: projector
        )

AngleSceneView(
            scene: vm.scene,
            cameraMode: $vm.cameraMode,
            interactionMode: is3D ? .cameraControl : .tapsOnly,
            autoFitsRotatedTable: !is3D,
            onPocketTapped: vm.isBreakMode || vm.isSequenceMode || vm.isPlaying ? nil : { vm.selectPocket(at: $0) },
            // 开球模式：仅母球可拖（限开球区）；序列模式：台面只读（逐杆演示），其余台面交互挂起。
            draggableBallNodes: (vm.isPlaying || vm.isSequenceMode) ? [] : (vm.breakRunner?.draggableCue ?? vm.draggableBalls),
            onDragBegan: { node in
                dismissBriefOnInteraction()
                if let runner = vm.breakRunner { runner.dragBegan(node: node) }
                else { vm.dragBegan(node: node) }
            },
            onDragMoved: { node, world in
                if let runner = vm.breakRunner {
                    runner.dragMoved(node: node, worldPosition: world)
                } else {
                    vm.dragMoved(node: node, worldPosition: world)
                }
            },
            onDragEnded: { node in
                if let runner = vm.breakRunner { runner.dragEnded(node: node) }
                else { vm.dragEnded(node: node) }
            },
            onDragEndedAt: { node, localPoint in
                guard !vm.isBreakMode else { return }
                handleTableDragEnd(node: node, localPoint: localPoint)
            },
            selectableBallNodes: (vm.isBreakMode || vm.isSequenceMode) ? [] : vm.selectableBalls,
            onBallTapped: { if !vm.isSequenceMode { vm.selectTarget(node: $0) } },
            onTableTapped: is3D ? nil : {
                dismissBriefOnInteraction()
                if !vm.isBreakMode && !vm.isSequenceMode { vm.handleTableTap(world: $0) }
            },
            onAimNudged: is3D ? nil : {
                dismissBriefOnInteraction()
                if vm.isSequenceMode { return }
                if let runner = vm.breakRunner { runner.nudgeAim(byDegrees: $0) }
                else { vm.nudgeFreeAim(byDegrees: $0) }
            },
            onAimDragActiveChanged: { vm.setAimTableDragging($0) },
            projector: projector
        )

AngleSceneView(
            scene: vm.scene,
            cameraMode: $vm.cameraMode,
            interactionMode: is3D ? .cameraControl : .tapsOnly,
            autoFitsRotatedTable: !is3D,
            onPocketTapped: is3D || vm.isBreakMode || vm.isPlaying ? nil : { vm.selectPocket(at: $0) },
            // 开球模式：仅母球可拖（限开球区），其余台面交互挂起。
            draggableBallNodes: vm.isPlaying ? [] : (vm.breakRunner?.draggableCue
                ?? (is3D || vm.activeTool == .none ? vm.draggableBalls : [])),
            onDragBegan: { node in
                if let runner = vm.breakRunner { runner.dragBegan(node: node) }
                else { vm.dragBegan(node: node) }
            },
            onDragMoved: { node, world in
                if let runner = vm.breakRunner { runner.dragMoved(node: node, worldPosition: world) }
                else { vm.dragMoved(node: node, worldPosition: world) }
            },
            onDragEnded: { node in
                if let runner = vm.breakRunner { runner.dragEnded(node: node) }
                else { vm.dragEnded(node: node) }
            },
            onDragEndedAt: { node, localPoint in
                guard !vm.isBreakMode else { return }
                handleTableDragEnd(node: node, localPoint: localPoint)
            },
            selectableBallNodes: (is3D || vm.isBreakMode || vm.activeTool != .none) ? [] : vm.selectableBalls,
            onBallTapped: { vm.selectTarget(node: $0) },
            // G18/V6：开球模式拖屏调瞄准（G13 相对语义）；非开球模式本页无自由拖瞄，忽略。
            onAimNudged: is3D ? nil : { if let runner = vm.breakRunner { runner.nudgeAim(byDegrees: $0) } },
            projector: projector
        )
